SELECT
  AVG(vc.alt_read_count::numeric / NULLIF(vc.total_read_count, 0)) FILTER (
    WHERE vc.filter_status = 'PASS' AND vc.total_read_count >= 20 AND s.is_control = false
  ) AS mean_allele_fraction,
  COUNT(*) FILTER (
    WHERE vc.filter_status = 'PASS' AND vc.total_read_count >= 20 AND s.is_control = false
  ) AS call_count
FROM world_cup.genomics.variant_calls vc
JOIN world_cup.genomics.samples s ON s.id = vc.sample_id;

